import React, { useEffect, useState } from 'react';
import styles from './Dashboard.module.css';
import { fetchPortfolio } from '../../api';

interface PortfolioItem {
  id: number;
  ticker: string;
  amount: number;
  buy_price: number;
  sell_price: number | null;
  buy_date: string;
  sell_date: string | null;
}

const Dashboard = () => {
  const [portfolioData, setPortfolioData] = useState<PortfolioItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadPortfolioData = async () => {
      try {
        const data = await fetchPortfolio({ active_only: true });
        setPortfolioData(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to fetch portfolio data');
      } finally {
        setLoading(false);
      }
    };

    loadPortfolioData();
  }, []);

  // Calculate portfolio metrics
  const totalInvested = portfolioData.reduce(
    (sum, item) => sum + item.amount * item.buy_price,
    0
  );

  const totalCurrentValue = portfolioData.reduce(
    (sum, item) => sum + item.amount * (item.sell_price || item.buy_price),
    0
  );

  const unrealizedProfit = totalCurrentValue - totalInvested;

  if (loading) {
    return <div className={styles.loading}>Loading dashboard data...</div>;
  }

  if (error) {
    return <div className={styles.error}>Error: {error}</div>;
  }

  return (
    <div className={styles.pageLayout}>
      {/* Container 1: Portfolio Overview */}
      <div className={styles.container}>
        <h1 className={styles.header}>Portfolio Overview</h1>
        <div className={styles.content}>
          <p>Total invested: ${totalInvested.toFixed(2)}</p>
          <p>The total holdings: ${totalCurrentValue.toFixed(2)}</p>
          <p className={unrealizedProfit >= 0 ? styles.profit : styles.loss}>
            Unrealised Profit: ${unrealizedProfit.toFixed(2)} (
            {(unrealizedProfit / totalInvested * 100).toFixed(2)}%)
          </p>
        </div>
      </div>

      {/* Container 2: Quantity */}
      <div className={styles.container}>
        <h2 className={styles.header}>Quantity</h2>
        <div className={styles.content}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>Ticker</th>
                <th>Amount</th>
                <th>Buy Price</th>
                <th>Current Value</th>
              </tr>
            </thead>
            <tbody>
              {portfolioData.map((item) => (
                <tr key={item.id}>
                  <td>{item.ticker}</td>
                  <td>{item.amount}</td>
                  <td>${item.buy_price.toFixed(2)}</td>
                  <td>${(item.amount * (item.sell_price || item.buy_price)).toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Container 3: Allocation */}
      <div className={styles.container}>
        <h3 className={styles.header}>Allocation</h3>
        <ul className={styles.list}>
          {portfolioData.map((item) => (
            <li key={item.id}>
              {item.ticker}: {((item.amount * item.buy_price / totalInvested) * 100).toFixed(2)}%
            </li>
          ))}
        </ul>
      </div>

      {/* Container 4: Sector distribution */}
      <div className={styles.container}>
        <h3 className={styles.header}>Sector distribution</h3>
        <p>Table content PLACEHOLDER (would need additional sector data)</p>
      </div>
    </div>
  );
};

export default Dashboard;
